-- Mod-authored natural wonder portrait descriptions, pl_PL overlay.
-- Baseline in CivVAccess_NaturalWonderDescStrings_en_US.lua.
CivVAccess_Strings = CivVAccess_Strings or {}

CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_MISSING"] = "Brak opisu tego cudu natury."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_FEATURE_CRATER"] =
    "Rozległy krater uderzeniowy widziany od krawędzi, poszarpana misa wbita w bladą pustynną ziemię. Bliższy stok pokrywają zielone zarośla, które opadają w zacieniony dół, którego dno tonie w głębokiej brunatnej ciemności, a dalsza krawędź wznosi się pasmami beżu i złota pod zamglonym niebem."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_FEATURE_EL_DORADO"] =
    "Schodkowa piramida z litego złota, ze stromymi schodami wspinającymi się po jej ścianie do małej kaplicy na szczycie. Wielkie złote sztaby spiętrzone są u jej podstawy wśród smukłych ciemnych drzew, a cała scena jarzy się żółtym blaskiem, skarb mitycznego miasta uczyniony dosłownym. Promienie światła za nią wyglądają jak wschód słońca wzbierający nad zaginionym miastem."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_FEATURE_FOUNTAIN_YOUTH"] =
    "Źródło niemożliwie jasnej turkusowej wody wzbiera z misy na szczycie ciemnych skalnych urwisk i spada w dół jarzącym się wodospadem do sadzawki poniżej. Kępy zielonej trawy czepiają się czarnej skały, liście palm oprawiają ciepłe złociste niebo, a drobne iskierki w wodzie znamionują ją jako magiczną, nie naturalną."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_FEATURE_FUJI"] =
    "Doskonały wulkaniczny stożek wypełnia kadr, a jego szeroka śnieżna czapa sięga niemal do połowy stoków. Śnieg namalowano miękką bielą i bladym błękitem na tle głębokiego niebieskiego nieba, a pas zielonych zarośli i zamglonej wody ciągnie się u stóp góry."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_FEATURE_GEYSER"] =
    "Gejzer wybucha z poszarpanego bladego wzniesienia, a jego biały rozprysk rozwija się wachlarzem, wypełniając całe niebo mgłą na tle błękitu. Ciemny wiecznie zielony las zamyka scenę po obu stronach, a pierwszy plan to skorupa mineralnych tarasów w barwach beżu, ochry i brązu."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_FEATURE_GIBRALTAR"] =
    "Wielki wapienny cypel wznosi się z płaskiego morza, strome blade urwiska na lewej ścianie i długi stok ciemnozielonej roślinności opadający po jego grzbiecie. Cała scena skąpana jest w złocie, a niebo i woda jarzą się jak późne popołudnie."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_FEATURE_KILIMANJARO"] =
    "Ogromna kopuła smugowana śniegiem wypełnia górną połowę kadru lodowatą bielą i błękitem, a u jej podstawy dryfuje pierścień małych chmur. Poniżej rozciąga się zielona sawanna, gdzie dwie żyrafy stoją przy bladym wodopoju, a drzewa o płaskich koronach rosną na skraju sceny."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_FEATURE_LAKE_VICTORIA"] =
    "Szerokie turkusowe jezioro cofa się ku bladym wzgórzom na horyzoncie, otoczone skalistymi brunatnymi występami po obu stronach. Pośrodku pierwszego planu wynurza się hipopotam, jego głowa i grzbiet przebijają pomarszczoną wodę, pod białą poświatą światła wypełniającą niebo."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_FEATURE_MESA"] =
    "Płaskoszczytowa mesa z warstwowej czerwono-pomarańczowej skały wznosi się samotnie z suchej równiny, prążkowane ściany urwisk ponad długimi stokami obsuniętego rumowiska. Rzadkie zielone zarośla cętkują piaszczystą ziemię u jej stóp, a płaski szczyt kreśli twardą linię na tle jaskrawego błękitnego nieba."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_FEATURE_MT_KAILASH"] =
    "Piramida z prążkowanej skały i śniegu wznosi się na tle głębokiego niebieskiego nieba, a jej pasiasta ściana oświetlona jest ciepłym złotem po jednej stronie. Poniżej cały pierwszy plan to surowe śnieżne pole i lodowe granie w zimnym niebieskim cieniu."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_FEATURE_MT_SINAI"] =
    "Skupisko poszarpanych pustynnych szczytów z pomarańczowo-brązowego piaskowca, głębokie żleby żłobią ich ściany, a zza środkowego wierzchołka przebija miękka poświata światła. Rozsiane głazy zaścielają piaszczystą równinę na pierwszym planie pod czystym błękitnym niebem."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_FEATURE_POTOSI"] =
    "Naga rdzawobrunatna góra, której niższe stoki pogrzebane są pod stosami szarych głazów połyskujących srebrną rudą. Ścieżka wije się po jej zboczu, rzędy ciemnych ociosanych bloków ustawione są u jej podstawy niczym wyrobiska kopalniane, a zakurzony szczyt rysuje się na tle błękitnego nieba."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_FEATURE_REEF"] =
    "Scena podwodna: koral tłoczy się po lewej stronie i u dołu kadru w barwach pomarańczu, czerwieni, fioletu i bladego błękitu, a wśród gałęzi sterczą pionowo gąbki rurkowate. Małe tropikalne ryby dryfują przez głęboką niebieską wodę, jedna jaskrawożółta pośrodku. Światło zanika w otwartą ciemność ku górnemu prawemu rogowi."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_FEATURE_SOLOMONS_MINES"] =
    "Monumentalna baszta bramna zastępująca legendarne kopalnie: wysoki ciemny mur fortecy uwieńczony blankami o złoconych szczytach, z wejściem pośrodku, flankowany brunatnymi kamiennymi wieżami. Przed nią blada skalna posadzka wyrzeźbiona jest w rozległe łuki, jakby sama ziemia została gładko wykuta."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_FEATURE_SRI_PADA"] =
    "Bujnie zielona góra wznosi się ku zaokrąglonemu szczytowi, dżungla pokrywa jej stoki poza miejscami, gdzie urwiskami przebija pomarańczowo-brązowa skała. Wysokie źdźbła trawy z drobnymi niebieskimi kwiatami wypełniają pierwszy plan, a niebo za nim jest żywym tropikalnym turkusem."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_FEATURE_ULURU"] =
    "Wielki czerwony monolit leży w średnim planie, jego zaokrąglona piaskowcowa bryła pobrużdżona pionowymi rowkami i jarząca się pomarańczem w świetle. Przed nim rozciągają się płaskie zarośla buszu, czerwona ziemia łatana niskimi zielonymi krzewami i kępami trawy, pod jaskrawym błękitnym niebem."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_FEATURE_VOLCANO"] =
    "Ciemny wulkaniczny stożek wznosi się z morza za pasem bladej turkusowej wody, widziany z porośniętego dżunglą brzegu, którego szerokie zielone liście oprawiają scenę. Niebo nad nim płonie siarczystą żółcią, a wątły kłąb dymu nad szczytem zapowiada nadchodzącą erupcję."
